function UIGamePlayGuideBookDialog:Awake()
    SetButtonAction(self.Btn_ClosePanel, function()
        UIModule.CloseDialog(self.controller)
    end)
    self.controller:SetSortOrder(300)
    
    ---@type Engine.UI.UIArgument
    local argument = self.controller.Argument
    self.indexTabOnShow = (isSet(argument, "parameters") and isSet(argument.parameters, "indexTab")) 
            and self.controller.Argument.parameters.indexTab or 1
    self.showType = (isSet(argument, "parameters") and isSet(argument.parameters, "showType"))
            and self.controller.Argument.parameters.showType or 1
    if self.controller then
        -- 战中才取消自动控制
        if BattleViewMgr and BattleViewMgr.battleState == Constants.BattleState.Processing then
            self.controller.IsAutoHandleNavBar = false
        end
    end
    self.animatorFinger = KTool.GetComponent(self.FingerNode.gameObject, typeof(Animator))
    self.stepNow = 0 -- 记录 动画当前 的进度
end

function UIGamePlayGuideBookDialog:OnFocus(focus)
end

function UIGamePlayGuideBookDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:InitConfMgr()
        coroutine.yield(self:InitPoolOBJOfGuideBook())  -- 初始化指南需要的特效
        coroutine.yield(self:FillSkillCard())
        self:FillCardSmall()
    end))
    return coWait
end

function UIGamePlayGuideBookDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            URPCameraController.Instance:SetMainCameraActive(false)
            self:SetMutexPageShowState(false)
            -- local capture = self.controller.gameObject:GetComponent(typeof(CS.UGUI.Effects.UIEffectCapturedImage))
            -- if not IsNull(capture) then capture:Capture() end
            self:InitComponent()
            if self.showType > 1 then
                KTool.SetActive(self.Root_ToggleFather.gameObject, false)
                local _orderTracker = self.controller.gameObject:GetComponent(typeof(OrderTrackerType))
                if not IsNull(_orderTracker) then
                    _orderTracker.addSortingOrder = 5
                end
            end
            self:SwitchTabBtn(self.indexTabOnShow)
            self:PlayPanelAnimator()
            SetButtonAction(self.BtnArrowRight, function()
                local indexPage = self.indexShowNow + 1 > self.numTab and 1 or self.indexShowNow + 1
                self.indexShowNow = indexPage
                self:SwitchTabBtn(self.indexShowNow)
            end)
            SetButtonAction(self.BtnArrowLeft, function()
                local indexPage = self.indexShowNow - 1 < 1 and self.numTab or self.indexShowNow - 1
                self.indexShowNow = indexPage
                self:SwitchTabBtn(self.indexShowNow)
            end)
        end)
    end))
    return coWait
end

function UIGamePlayGuideBookDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.coPlayAnim then
            cs_coroutine.stop(self.coPlayAnim)
        end
        if self.coPlayingAnimation then
            cs_coroutine.stop(self.coPlayingAnimation)
        end
        if self.coShowInSkillPool then
            cs_coroutine.stop(self.coShowInSkillPool)
        end
        if self.coShowOnTweenCompleted then
            cs_coroutine.stop(self.coShowOnTweenCompleted)
        end
        if self.coPage2 then
            cs_coroutine.stop(self.coPage2)
        end
        local listTween = DOTween.TweensById(TAG_TWEEN, false)
        -- print("->UIGamePlayGuideBookDialog:OnFinalize:", not IsNull(listTween) and table.dump(listTween))
        DOTween.Pause(TAG_TWEEN)
        DOTween.Kill(TAG_TWEEN)
        UIBattlingCtrlMgr:GetInstance():SetBooleanOpenDetection(true)
        
        local battleDialog = UIBattlingCtrlMgr:GetInstance():GetBattlingDialog()
        if battleDialog then
            battleDialog.switchGameOverIn = 0
            if not IsNull(battleDialog.btnSaveRecord) then
                KTool.SetActive(battleDialog.btnSaveRecord, false)
            end
        end

        -- 战中不用清理，战斗外要清理
        if IsNull(BattleViewMgr) then
            self:ClearObjPools()    -- 删除指南需要的特效
        else
            -- 战中要打开一下主相机
            URPCameraController.Instance:SetMainCameraActive(true)
        end
        self:SetMutexPageShowState(true)
        
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的 gc
    end))
    return coWait
end
