---InitSkillPool
---初始化技能卡池
function UIGamePlayGuideBookDialog:InitSkillPool(type)
    local skillList = SkillListIds[tostring(type)]
    local skillTopLine = self.panelSkillPool.skillPoolTransArrLineTop -- 卡池行1
    local skillDownLine = self.panelSkillPool.skillPoolTransArrLineDown -- 卡池行2
    for i = 1, #skillTopLine do
        skillTopLine[i].luaBehaviour = nil
        skillDownLine[i].luaBehaviour = nil
    end
    DOTween.Pause(TAG_TWEEN)
    --- 重置卡池
    for i = 1, 5 do
        local skillCard = self.listSkillCard[i]
        local lbSkillCard = skillCard.controller
        skillCard:CleanAllEffect()
        skillTopLine[i].luaBehaviour = lbSkillCard

        local cardPosition = skillTopLine[i].position
        KTool.SetParent(lbSkillCard.gameObject, cardPosition.gameObject, true)

        lbSkillCard.transform.localPosition = Vector3.zero
        lbSkillCard.transform.localRotation = Quaternion.Euler(0, 0, 0)
        lbSkillCard.transform.localScale = Vector3.one

        local skillData = skillList[1][i]
        self:SetSkillCardInfo(skillCard, skillData)
        skillCard.curFatherTrans = skillTopLine[i].position
        skillCard.curGOCanvasGroup.alpha = 1
        KTool.SetActive(lbSkillCard.gameObject, true)

        skillCard = self.listSkillCard[i + 5]
        lbSkillCard = skillCard.controller
        skillCard:CleanAllEffect()

        skillDownLine[i].luaBehaviour = lbSkillCard
        cardPosition = skillDownLine[i].position
        KTool.SetParent(lbSkillCard.gameObject, cardPosition.gameObject, true)

        lbSkillCard.transform.localPosition = Vector3.zero
        lbSkillCard.transform.localRotation = Quaternion.Euler(0, 0, 0)
        lbSkillCard.transform.localScale = Vector3.one

        skillData = skillList[2][i]
        self:SetSkillCardInfo(skillCard, skillData)
        skillCard.curFatherTrans = skillDownLine[i].position
        skillCard.curGOCanvasGroup.alpha = 1
        KTool.SetActive(lbSkillCard.gameObject, true)
    end
end

------------ Page_1 ------------

function UIGamePlayGuideBookDialog:AnimationPage2_2()
    --- 技能卡拖动
    local goStartPos = self.panelSkillPool:GetSkillCardByPos(2, 4).luaBehaviour.gameObject
    self:PlayAnimationFingerDrag(goStartPos)
    --- 技能卡被交换位置
    local transEndPos = self.panelSkillPool:GetSkillCardByPos(1, 2).position
    --- 被合成
    local goLineEnd = self.panelSkillPool:GetSkillCardByPos(1, 2).luaBehaviour.gameObject
    local transLineEnd = self.panelSkillPool:GetSkillCardByPos(1, 2).position
    KTool.SetParent(goStartPos, self.panelSkillPool.controller.gameObject, true)
    local tween = goStartPos.transform:DOMove(transEndPos.position, 1.5):SetDelay(1.2)
    tween.stringId = TAG_TWEEN
    tween.onComplete = function()
        --- 开始合成表现
        self:AnimationPage2_2OnTweenCompleted()
    end
    self.coShowInSkillPool = cs_coroutine.start(function()
        local state = 1 --- 控制动画阶段
        local lineRenderer
        local ptcSkillCardUnitShow_1
        local ptcSkillCardUnitShow_2
        while tween.IsActive(tween) and tween.ElapsedPercentage(tween, true) do
            local process = tween.ElapsedPercentage(tween, true)
            if state < 2 and process > 0.5 then
                state = 3 -- 修改状态值
                --- 预合成表现 ptc
                ptcSkillCardUnitShow_1 = self:SetPanelPTC(Constants.UIBattlingObjPoolPTC.PTC_CARD_SKILLCARD_UNITSHOW_STAR1, goStartPos, 9999, LAYER_PTC, true)
                ptcSkillCardUnitShow_2 = self:SetPanelPTC(Constants.UIBattlingObjPoolPTC.PTC_CARD_SKILLCARD_UNITSHOW_STAR1, goLineEnd, 9999, LAYER_PTC, true)
            end
            --- 已经到达表现位置
            if state > 2 then
                if IsNull(lineRenderer) then
                    --- 线渲染器  
                    local goLineRenderer = self:SetPanelPTC(Constants.UIBattlingObjPoolPTC.PTC_CARD_SKILLCARD_UNITSHOW_LINE, self.SkillCardsPool.gameObject.transform, 9999,true, true)
                    lineRenderer = KTool.GetOrAddComponent(goLineRenderer, typeof(CS.LineRenderersController))
                    if lineRenderer then
                        lineRenderer:SetOrder(LAYER_PTC)
                    end
                end
                if lineRenderer then
                    local pos_1 = goStartPos.transform.localPosition
                    local pos_2 = transLineEnd.localPosition
                    lineRenderer:SetPositions(pos_1, pos_2)
                end
            end
            cs_coroutine.yield_return()
        end
        if lineRenderer then
            UIBattlingTools.RecyclePoolObj(lineRenderer.gameObject)
        end
        if ptcSkillCardUnitShow_1 then
            UIBattlingTools.RecyclePoolObj(ptcSkillCardUnitShow_1)
        end
        if ptcSkillCardUnitShow_2 then
            UIBattlingTools.RecyclePoolObj(ptcSkillCardUnitShow_2)
        end
        self.coShowInSkillPool = nil
    end)
end


---AnimationPage1
---页面 1 的动画序列
function UIGamePlayGuideBookDialog:AnimationPage2()
    self:SetCardSmallDefault()
    self:InitSkillPool(2)
    --- 技能卡拖动
    local goStartPos = self.panelSkillPool:GetSkillCardByPos(1, 4).luaBehaviour.gameObject
    self:PlayAnimationFingerDrag(goStartPos)
    --- 技能卡被交换位置
    local transEndPos = self.panelSkillPool:GetSkillCardByPos(2, 2).position
    --- 被合成
    local goLineEnd = self.panelSkillPool:GetSkillCardByPos(2, 1).luaBehaviour.gameObject
    local transLineEnd = self.panelSkillPool:GetSkillCardByPos(2, 1).position
    KTool.SetParent(goStartPos, self.panelSkillPool.controller.gameObject, true)
    local tween = goStartPos.transform:DOMove(transEndPos.position, 1.5):SetDelay(1.2)
    --tween:SetId(TAG_TWEEN)
    tween.stringId = TAG_TWEEN
    tween.onComplete = function()
        --- 开始合成表现
        self:AnimationPage2OnTweenCompleted()
    end

    self.coShowInSkillPool = cs_coroutine.start(function()
        local state = 1 --- 控制动画阶段
        local lineRenderer
        local ptcSkillCardUnitShow_1
        local ptcSkillCardUnitShow_2
        while tween.IsActive(tween) and tween.ElapsedPercentage(tween, true) do
            local process = tween.ElapsedPercentage(tween, true)
            if state < 2 and process > 0.5 then
                state = 3 -- 修改状态值
                --- 预合成表现 ptc
                ptcSkillCardUnitShow_1 = self:SetPanelPTC(Constants.UIBattlingObjPoolPTC.PTC_CARD_SKILLCARD_UNITSHOW_STAR1, goStartPos, 9999, LAYER_PTC, true)
                ptcSkillCardUnitShow_2 = self:SetPanelPTC(Constants.UIBattlingObjPoolPTC.PTC_CARD_SKILLCARD_UNITSHOW_STAR1, goLineEnd, 9999, LAYER_PTC, true)
            end
            --- 已经到达表现位置
            if state > 2 then
                if IsNull(lineRenderer) then
                    --- 线渲染器  
                    local goLineRenderer = self:SetPanelPTC(Constants.UIBattlingObjPoolPTC.PTC_CARD_SKILLCARD_UNITSHOW_LINE, self.SkillCardsPool.gameObject.transform, 9999,true, true)
                    lineRenderer = KTool.GetOrAddComponent(goLineRenderer, typeof(CS.LineRenderersController))
                    if lineRenderer then
                        lineRenderer:SetOrder(LAYER_PTC)
                    end
                end
                if lineRenderer then
                    local pos_1 = goStartPos.transform.localPosition
                    local pos_2 = transLineEnd.localPosition
                    lineRenderer:SetPositions(pos_1, pos_2)
                end
            end
            cs_coroutine.yield_return()
        end
        if lineRenderer then
            UIBattlingTools.RecyclePoolObj(lineRenderer.gameObject)
        end
        if ptcSkillCardUnitShow_1 then
            UIBattlingTools.RecyclePoolObj(ptcSkillCardUnitShow_1)
        end
        if ptcSkillCardUnitShow_2 then
            UIBattlingTools.RecyclePoolObj(ptcSkillCardUnitShow_2)
        end
        self.coShowInSkillPool = nil
    end)
end

---AnimationPage2OnTweenCompleted
---Tween 执行完之后执行的协程
--- 位置交换 41 22
--- 合成 21 11
--- 合成 22 21 
function UIGamePlayGuideBookDialog:AnimationPage2OnTweenCompleted()
    self.coShowOnTweenCompleted = cs_coroutine.start(function()
        self:PlayAnimationFingerDrag()
        self:CardSmallMove(self.listCardSmall[1]) -- 移动占位牌
        self.panelSkillPool:SkillCardExchangePos({ s = { 4, 1 }, d = { 2, 2 } })
        self:CardUnitByGuideBook({ s = { 2, 2 }, d = { 1, 2 } })
