        self:CardUnitByGuideBook({ s = { 2, 1 }, d = { 2, 2 } })
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(2))
        self:AnimationPage2_2()
        self.coShowOnTweenCompleted = nil
    end)
end

function UIGamePlayGuideBookDialog:AnimationPage2_2OnTweenCompleted()
    self.coShowOnTweenCompleted = cs_coroutine.start(function()
        self:PlayAnimationFingerDrag()
        self:CardSmallMove(self.listCardSmall[2]) -- 移动占位牌
        self:CardUnitByGuideBook({ s = { 4, 2 }, d = { 2, 1 } })
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(2))
        self:AnimationPage2()
        self.coShowOnTweenCompleted = nil
    end)
end

