---CardUnitByGuideBook
---页面合卡方法
---@param data table
function UIGamePlayGuideBookDialog:CardUnitByGuideBook(data)
    local moveObjLine = data.s[2] -- 出现空位的 行
    local moveSkillCardPos = data.s[1] -- 移动消失的 技能牌
    local targetObjLine = data.d[2]
    local upgradeSkillCardPos = data.d[1] -- 升级的 技能牌

    local moveLine = self.panelSkillPool:SelectSkillCardAimLine(moveObjLine)
    local targetLine = self.panelSkillPool:SelectSkillCardAimLine(targetObjLine)
    local unitType = (targetObjLine == moveObjLine) and 2 or 1
    local moveSkillCardLB = moveLine[moveSkillCardPos].luaBehaviour
    local upgradeSkillCardLB = targetLine[upgradeSkillCardPos].luaBehaviour

    --UIBattlingTools.PlayAudio(Constants.UIBattleAudio.UnitSkillCard)
    --- 被融合卡牌表现
    local skillCardBeUnit = moveSkillCardLB.Env
    self:AnimationSkillCardBeUnit(skillCardBeUnit, unitType)
    --- 晋升卡牌表现
    local skillCardUpgrade = upgradeSkillCardLB.Env
    --- 晋升卡牌 动画
    local animaPart_1_Name = unitType == 1 and "Card_Combine_L_to_R" or "Card_Combine_T_to_B"
    local animaPart_2_Name = unitType == 1 and "Card_Combine_VH" or "Card_Combine_VH_Vertical"
    --- 重置父节点 坐标
    skillCardUpgrade:SkillCardPosReset()
    ---PTC_Unit_Rota
    self:SetPanelPTC(Constants.UIBattlingObjPoolPTC.PTC_CARD_UNIT_ROTATION_NAME, skillCardUpgrade.ParticalRoot.gameObject, 3, LAYER_PTC, true)
    skillCardUpgrade.curAnimation:Play(animaPart_1_Name)
    while not IsNull(skillCardUpgrade.curAnimation) and skillCardUpgrade.curAnimation.isPlaying do
        cs_coroutine.yield_return()
    end
    ---PTC_Unit_p2
    self:SetPanelPTC(Constants.UIBattlingObjPoolPTC.PTC_CARD_UNIT_PART2_NAME, skillCardUpgrade.ParticalRoot.gameObject, 3, LAYER_PTC, true)
    skillCardUpgrade.curAnimation:Play(animaPart_2_Name)
    ---卡牌升级表现
    self:SetSkillCardInfo(skillCardUpgrade, {
        skillId = skillCardUpgrade.skillCardSkillId,
        star = 2,
        skillLv = 1,
        attributeType = skillCardUpgrade.attributeType
    })
    while not IsNull(skillCardUpgrade.curAnimation) and skillCardUpgrade.curAnimation.isPlaying do
        cs_coroutine.yield_return()
    end
    ---PTC_Unit_Upg
    local starEX = 1
    local name = starEX < 2 and Constants.UIBattlingObjPoolPTC.PTC_STAR2_Name or Constants.UIBattlingObjPoolPTC.PTC_STAR3_Name
    self:SetPanelPTC(name, skillCardUpgrade.ParticalRoot.gameObject, 1, LAYER_PTC, true)
    --UIBattlingTools.PlayAudio(Constants.UIBattleAudio.UnitFinishSkillCard)
    --- 被融合卡牌逻辑位置 置空
    moveLine[moveSkillCardPos].luaBehaviour = nil
    cs_coroutine.yield_return()
    --- 卡牌 规整
    cs_coroutine.yield_return(self.panelSkillPool:SkillCardArrange(moveObjLine, moveSkillCardPos))
    -- if ptcUnitRota then
    --     UIBattlingTools.RecyclePoolObj(ptcUnitRota)
    -- end
    -- if ptcUnitP2 then
    --     UIBattlingTools.RecyclePoolObj(ptcUnitP2)
    -- end
    -- if ptcUnitUpg then
    --     UIBattlingTools.RecyclePoolObj(ptcUnitUpg)
    -- end
end
