---CardUsedByGuideBook
---卡牌使用
---@param line number 行
---@param pos number 位置
function UIGamePlayGuideBookDialog:CardUsedByGuideBook(line, pos)
    local aimLine = self.panelSkillPool:SelectSkillCardAimLine(line)
    if IsNull(aimLine[pos].luaBehaviour) then return end
    local skillCard = aimLine[pos].luaBehaviour.Env
    if IsNull(skillCard) then return end
    local transSkillCard = skillCard.controller.transform
    self:PlayAnimationFingerPoint(transSkillCard.position)
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.15))
    transSkillCard.anchoredPosition = Vector2.zero
    transSkillCard:SetRotationZ(0) -- 恢复旋转
    transSkillCard.localScale = Vector3.one
    skillCard:SetSkillCardAlphaZero()
    skillCard:SetSkillCardPtcDefault()
    KTool.SetActive(skillCard.controller.gameObject, false)
    return skillCard.skillCardData, transSkillCard.position
end

function UIGamePlayGuideBookDialog:AnimationSkillCardBeUnit(skillCard, type)
    if IsNull(skillCard.curAnimation) then
        return
    end
    local animaName = type == 1 and "Card_Combine_R_to_L" or "Card_Combine_B_to_T"
    if IsNull(animaName) then
        return
    end
    --- 重置父节点 坐标
    skillCard:SkillCardPosReset()
    --- PTC_Unit_Rotation
    skillCard.curAnimation:Play(animaName)
    self.coPlayAnim = cs_coroutine.start(
            function()
                while skillCard.curAnimation.isPlaying do
                    cs_coroutine.yield_return()
                end
                KTool.SetActive(skillCard.controller.gameObject, false)
            end)
end

