---FillDialogPage
---填充 页面节点
function UIGamePlayGuideBookDialog:FillDialogPage()
    if IsNull(self.listDialogPage) then
        self.listDialogPage = {}
    end
    if self.Root_Page then
        --- 节点子节点数量
        local rootChildCount = self.Root_Page.childCount
        for i = 1, rootChildCount do
            local transPage = self.Root_Page:GetChild(i - 1)
            if transPage then
                table.insert(self.listDialogPage, transPage.gameObject)
            end
        end
    end
end

---SetTabBtn
---设置页签切换按钮
---@param num number 页签数量
function UIGamePlayGuideBookDialog:SetTabBtn(num)
    --- 页签按键游戏物体
    local goTabBtn = self.PageNumToggle.gameObject
    if not IsNull(goTabBtn) then
        for i = 1, num do
            local goBtn = GameObject.Instantiate(goTabBtn, self.Root_ToggleFather.transform)
            KTool.SetActive(goBtn.gameObject, true)
            local compToggle = goBtn.gameObject:GetComponent(typeof(Toggle))
            local lbToggleNode = GetLuaBehaviour(goBtn, PATH_TABLE_TOGGLE)
            local ltToggleNode
            if lbToggleNode then
                lbToggleNode:Init()
                ltToggleNode = lbToggleNode.Env
                ltToggleNode:SetTabIndex(i)
            end
            SetToggleValueChanged(compToggle, function(value)
                --- 页面的 Index
                local indexPage = i
                if value and self.indexShowNow == indexPage then
                    return
                end
                if value then
                    self.indexShowNow = indexPage
                    self:SetTitleDesc(indexPage)
                end
                self:ChangePanelPageShowState(indexPage, value)
                ltToggleNode:SetTabState(value)
            end)
            --- 设置初始页签状态
            if i == 1 then
                if ltToggleNode then
                    ltToggleNode:SetTabState(true)
                end
            end
            table.insert(self.listTabBtn, ltToggleNode)
        end
        --self.indexShowNow = 1
        --self:ChangePanelPageShowState(self.indexShowNow, true)
        --self:SetTitleDesc(self.indexShowNow)
    end
end

function UIGamePlayGuideBookDialog:SwitchTabBtn(value)
    self.indexShowNow = value
    self:SetTitleDesc(self.indexShowNow)
    -- print("->UIGamePlayGuideBookDialog:SwitchTabBtn:", table.dump(self.listTabBtn))
    for i, btn in pairs(self.listTabBtn) do
        if btn:GetTabIndex() ~= value then
            self:ChangePanelPageShowState(btn:GetTabIndex(), false)
        end
        btn:SetTabState(btn:GetTabIndex() == value)
        btn.toggle.isOn = btn:GetTabIndex() == value
    end
    self:ChangePanelPageShowState(self.indexShowNow, true)
end

---SetPanelPageInfo
---设置页面信息
function UIGamePlayGuideBookDialog:SetPanelPageInfo()
    if IsNull(self.listDialogPage) then return end
    for i = 1, #self.listDialogPage do
        local pageObj = self.listDialogPage[i]
        local pageData = self.gamePlayBookConfMgr:GetConfDataByIndexTab(i)
        local pageDescData = pageData.arrTabDesc
        self:SetPageDesc(pageObj, pageDescData)
    end
end

---SetPageDesc
---设置页面描述
---@param pageObj UnityEngine.GameObject 页面的 GameObject
---@param pageDescData table 页面的指南描述集合
function UIGamePlayGuideBookDialog:SetPageDesc(pageObj, pageDescData)
    local compTextsInPage
    local arrCompTextsInPage = pageObj:GetComponentsInChildren(typeof(Text))
    if arrCompTextsInPage.Length > 0 then
        compTextsInPage = {}
        for i = 0, arrCompTextsInPage.Length - 1 do
            local nodeName = arrCompTextsInPage[i].gameObject.name
            compTextsInPage[checkString(nodeName)] = arrCompTextsInPage[i]
        end
    end
    if IsNull(compTextsInPage) then return end
    for i = 1, #pageDescData do
        local nameDescNode = PATH_TITLE_PAGE_DESC .. tostring(i)
        local txtDescNode = compTextsInPage[nameDescNode]
        if txtDescNode then
            txtDescNode.text = checkString(pageDescData[i])
        end
    end
end

---SetTitleDesc
---设置页签标题
---@param index number 页签 index
function UIGamePlayGuideBookDialog:SetTitleDesc(index)
    local pageData = self.gamePlayBookConfMgr:GetConfDataByIndexTab(index)
    if pageData then
        local strTitle = pageData.strTitle
        if self.TxtGuideTitle and self.TxtGuideTitle.text then
            self.TxtGuideTitle.text = checkString(strTitle)
        end
    end
end

---ChangePanelPageShowState
---切换页面
---@param index number
---@param boolean boolean
function UIGamePlayGuideBookDialog:ChangePanelPageShowState(index, boolean)
    if self.listDialogPage then
        local aimPage = self.listDialogPage[index]
        if aimPage then
            KTool.SetActive(aimPage, boolean)
            self:SetPageAnimationState(index, boolean)
        end
    end
end

---CleanPageCo
---清理页面协程
function UIGamePlayGuideBookDialog:CleanPageCo()
    if self.coShowInSkillPool then
        cs_coroutine.stop(self.coShowInSkillPool)
        self.coShowInSkillPool = nil
    end
    if self.coShowOnTweenCompleted then
        cs_coroutine.stop(self.coShowOnTweenCompleted)
    end
    if self.coPage2 then
        cs_coroutine.stop(self.coPage2)
    end
    if self.coPlayAnim then
        cs_coroutine.stop(self.coPlayAnim)
        self.coPlayAnim = nil
    end
end

---SetPageAnimationState
---播放页签页相应动画
---@param indexPage number 页签 Index
---@param boolean boolean 页面状态
function UIGamePlayGuideBookDialog:SetPageAnimationState(indexPage, boolean)
    if IsNull(self.AnimatorPlayer_Pages) then return end
    if self.coDisabledAnimator then
        cs_coroutine.stop(self.coDisabledAnimator)
        self.coDisabledAnimator = nil
    end
    --- 处理关闭页面的动画播放逻辑
    if not boolean then
        if self.coPlayingAnimation then
            cs_coroutine.stop(self.coPlayingAnimation)
            self.coPlayingAnimation = nil
        end
        if self.coDisabledAnimator then
            cs_coroutine.stop(self.coDisabledAnimator)
            self.coDisabledAnimator = nil
        end
        
        local animator = self.AnimatorPlayer_Pages
        local clipCount = animator:GetCurrentAnimatorClipInfoCount(0)
        if clipCount > 0 then
            local animationName = animator:GetCurrentAnimatorClipInfo(0)[0].clip.name
            animator:Play(animationName, 0, 0)
            animator:Update(0)
            animator.enabled = false
        end
        self:CleanPageCo()
        self:CleanListPTC()
        self:SetCardSmallDefault()
        DOTween.Pause(TAG_TWEEN)
    end
    --- 处理打开页面的动画播放逻辑
    if boolean then
        if indexPage == INDEX_PAGE then
            self.stepNow = 0
        end
        local pageAnimationName = ANIMATION_LIST_PAGES[tostring(indexPage)]
        --local loopStatus = checkInt(self.gamePlayBookConfMgr:GetConfDataByIndexTab(indexPage).ifLoop) --动画是否循环(0.循环 1.不循环)
        --self.curPageAnimationLoop = loopStatus < 1
        local clip = UIBattlingTools.GetAnimationClip(self.AnimatorPlayer_Pages, pageAnimationName)
        -- print("->UIGamePlayGuideBookDialog:SetPageAnimationState:", pageAnimationName, self.curPageAnimationLoop, clip.length)
        --local animationLength = clip.length + PAGE_ANIMATION_LENGTH_DELAY
        if pageAnimationName then
            --- 播放页面动画
            self.AnimatorPlayer_Pages.enabled = true
            self.AnimatorPlayer_Pages:Play(pageAnimationName)
            --self:GetSpecialActionOnAnimation(indexPage)
            --if not self.curPageAnimationLoop then
            --    self.coDisabledAnimator = cs_coroutine.start(function()
            --        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(animationLength))
            --        self.AnimatorPlayer_Pages.enabled = false
            --    end)
            --end
        end
        ---需要播放协程动画的页面
        self:SelectPageCoShowToPlay(indexPage)
    end
end

---SelectPageCoShowToPlay
---选择需要协程动画的页面
