        self:SetRootCardSmallShowState(true)
        self:AnimationPage1()
    elseif index == 2 then
        self:HideSkillPoolComponent()
        local skillData_1 = { skillId = 71103008, star = 1, skillLv = 1}
        local skillData_2 = { skillId = 72103008, star = 1, skillLv = 1}
        self.coPage2 = cs_coroutine.start(function()
            xTry(function()
                while true do
                    skillData_1.star = 1
                    skillData_2.star = 1
                    self:SetSkillCardInfo(self.page2_skillCard_1, skillData_1)
                    self:SetSkillCardInfo(self.page2_skillCard_2, skillData_2)
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.5))
                    skillData_1.star = 2
                    skillData_2.star = 2
                    self:SetSkillCardInfo( self.page2_skillCard_1, skillData_1)
                    self:SetSkillCardInfo( self.page2_skillCard_2, skillData_2)
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.5))
                    skillData_1.star = 3
                    skillData_2.star = 3
                    self:SetSkillCardInfo( self.page2_skillCard_1, skillData_1)
                    self:SetSkillCardInfo( self.page2_skillCard_2, skillData_2)
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.5))
                end
            end)
        end)
    --    self:SetRootSkillPoolShowState(SKILL_POOL_SHOW_STATE.LargeSize)
    --    self:SetRootUnitSkillShowState(false)
    --    self:SetRootCardSmallShowState(true)
        --self:AnimationPage2()
    -- elseif index == 8 then
    --     self:SetRootSkillPoolShowState(SKILL_POOL_SHOW_STATE.SmallSize)
    --     self:SetRootUnitSkillShowState(true)
    --     self:SetRootCardSmallShowState(true)
    --     self:AnimationPage9()
    else
       self:HideSkillPoolComponent()
    end
end

function UIGamePlayGuideBookDialog:HideSkillPoolComponent()
    self:SetRootSkillPoolShowState(SKILL_POOL_SHOW_STATE.Hide)
    self:SetRootUnitSkillShowState(false)
    self:SetRootCardSmallShowState(false)
    self:CleanPageCo()
    self:CleanListPTC()
    self:SetCardSmallDefault()
    self:PlayAnimationFingerPoint()
    DOTween.Pause(TAG_TWEEN)
end

---SetRootSkillPoolShowState
---改变 技能卡池 节点的显示状态
---@param showType integer @ SKILL_POOL_SHOW_STATE 显示状态
function UIGamePlayGuideBookDialog:SetRootSkillPoolShowState(showType)
    if showType == SKILL_POOL_SHOW_STATE.LargeSize then
        self.rectPanelSkillPool.anchoredPosition = SKILL_POOL_POS_1
        self.rectPanelSkillPool.localScale = Vector3.New(0.75, 0.75, 0)
    elseif showType == SKILL_POOL_SHOW_STATE.SmallSize then
        self.rectPanelSkillPool.anchoredPosition = SKILL_POOL_POS_2
        self.rectPanelSkillPool.localScale = Vector3.New(0.75, 0.75, 0)
    else
        self.rectPanelSkillPool.anchoredPosition = Vector2.New(9999, 9999)
        self.rectPanelSkillPool.localScale = Vector3.one
    end
    KTool.SetActive(self.rectPanelSkillPool, not (showType > 2))
end

