---GetSpecialActionOnAnimation
---获取当前页面需要在动画中执行的逻辑
---@param index number 页面Index
function UIGamePlayGuideBookDialog:GetSpecialActionOnAnimation(index)
    if index == 4 then
        --self:SetSkillCardInfo(self.SkillCardNode_1.Env,
        --        { skillId = SAMPLE_SP_SKILL_CARD, star = 1, skillLv = 1, attributeType = SKILL_CARD_ATTRIBUTE_TYPE })
    end
    local dataAct = SPECIAL_ACTION_LIST[tostring(index)]
    if IsNull(dataAct) then return end
    --- 当前页面的 Animator 组件
    local animator = self.AnimatorPlayer_Pages
    --- 动画执行协程
    self.coPlayingAnimation = cs_coroutine.start(function()
        while animator.enabled do
            --- 当前 动画播放时间
            local currentTime = animator:GetCurrentAnimatorStateInfo(0).normalizedTime
            --- 动画当前帧
            local currentFrame = UIBattlingTools.GetAnimatorCurrentFrame(animator, currentTime)
            self:DoSpecialActionOnAnimation(3, currentFrame)
            --if self.AnimatorPlayer_Pages.IsPlaying then
            --    --- 当前 动画播放时间
            --    local currentTime = animator:GetCurrentAnimatorStateInfo(0).normalizedTime
            --    --- 动画当前帧
            --    local currentFrame = UIBattlingTools.GetAnimatorCurrentFrame(animator, currentTime)
            --    self:DoSpecialActionOnAnimation(3, currentFrame)
            --else
            --    local animationName = animator:GetCurrentAnimatorClipInfo(0)[0].clip.name
            --    animator:Play(animationName, 0, 0)
            --    animator:Update(0)
            --    self.stepNow = 0
            --    self.AnimatorPlayer_Pages:Play(animationName)
            --end
            cs_coroutine.yield_return()
        end
    end)
end

---DoSpecialActionOnAnimation
---执行动画中操作
---@param indexList number
---@param frame table
function UIGamePlayGuideBookDialog:DoSpecialActionOnAnimation(indexList, frame)
    if indexList == 3 then
        if frame <= 0 and self.stepNow < 1 then
            self.stepNow = 1
            self:SetSkillCardInfo(self.SkillCardNode_1.Env,
                    { skillId = SAMPLE_SKILL_CARD, star = 1, skillLv = 1, attributeType = SKILL_CARD_ATTRIBUTE_TYPE })
            self:SetSkillCardInfo(self.SkillCardNode_2.Env,
                    { skillId = SAMPLE_SKILL_CARD, star = 1, skillLv = 1, attributeType = SKILL_CARD_ATTRIBUTE_TYPE })
        elseif frame >= 40 and frame < 101 and self.stepNow < 2 then
            self.stepNow = 2
            self:SetSkillCardInfo(self.SkillCardNode_1.Env,
                    { skillId = SAMPLE_SKILL_CARD, star = 2, skillLv = 1, attributeType = SKILL_CARD_ATTRIBUTE_TYPE })
            self:SetSkillCardInfo(self.SkillCardNode_2.Env,
                    { skillId = SAMPLE_SKILL_CARD, star = 2, skillLv = 1, attributeType = SKILL_CARD_ATTRIBUTE_TYPE })
        elseif frame >= 101 and self.stepNow < 3 then
            self.stepNow = 3
            self:SetSkillCardInfo(self.SkillCardNode_1.Env,
                    { skillId = SAMPLE_SKILL_CARD, star = 3, skillLv = 1, attributeType = SKILL_CARD_ATTRIBUTE_TYPE })
        end
    end
end

---SetPanelPTC
---设置页面 PTC
---@param ptcName string
---@param father UnityEngine.Transform
---@param duration number
---@param layer number
function UIGamePlayGuideBookDialog:SetPanelPTC(ptcName, father, duration, layer, nativeScale)
    local ptcBeUnit = UIBattlingTools.ReloadPTCOfBattling(ptcName, father, duration, nativeScale)
    if layer then
        -- UIBattlingTools.SetPTCOrderInLayer(ptcBeUnit, layer)
        local psList = ptcBeUnit.transform:GetComponentsInChildren(typeof(ParticleSystem))
        for i = 0, psList.Length - 1, 1 do
            local renderer = psList[i]:GetComponent(typeof(Renderer))
            renderer.sortingOrder = layer
        end
    end
    if IsNull(self.listPTC) then
        self.listPTC = {}
    end
    table.insert(self.listPTC, ptcBeUnit)
    return ptcBeUnit
end

---CleanListPTC
---清理缓存的粒子列表
function UIGamePlayGuideBookDialog:CleanListPTC()
    if IsNull(self.listPTC) then
        return
    end
    for i = 1, #self.listPTC do
        if not isNull(self.listPTC[i]) then
            UIBattlingTools.RecyclePoolObj(self.listPTC[i])
        end
    end
    self.listPTC = nil
end

---SetCardSmallDefault
---设置序列技能卡为默认状态
function UIGamePlayGuideBookDialog:SetCardSmallDefault()
    if self.listCardSmall then
        for i, v in ipairs(self.listCardSmall) do
            local card = v
            card:SetSequeneSkillCardDefaut()
            card:SetSkillCardShowState(true)
        end
    end
end

