------------ SkillCardInfo ------------
function UIGamePlayGuideBookDialog:SetSkillCardInfo(skillCard, data)
    if skillCard.class.RemoveListener then
        skillCard:RemoveListener()
    end
    skillCard:SetSkillCardData(data)

    --------------------- GetComp
    local cardIcon = skillCard.cardIcon
    local cardBG = skillCard.cardBG
    local cardFrame = skillCard.cardFrame
    local cardIndex = skillCard.cardIndex
    local cardTypeIcon = skillCard.cardTypeIcon
    local cardTypeBG = skillCard.cardTypeBG
    
    local compCardIcon = KTool.GetOrAddComponent(cardIcon.gameObject, typeof(RawImageAlterable))
    local compCardBG = KTool.GetOrAddComponent(cardBG.gameObject, typeof(RawImageAlterable))
    local compCardFrame = KTool.GetOrAddComponent(cardFrame.gameObject, typeof(RawImageAlterable))
    local compCardIndex = KTool.GetOrAddComponent(cardIndex.gameObject, typeof(RawImageAlterable))
    local compCardTypeIcon = KTool.GetOrAddComponent(cardTypeIcon.gameObject, typeof(RawImageAlterable))
    local compCardTypeBG = KTool.GetOrAddComponent(cardTypeBG.gameObject, typeof(RawImageAlterable))
    --------------------- GetComp
    
    --------------------- SetInfo
    local _SetCardIcon = function()
        skillCard:GetSkillCardIconPath()
        compCardIcon:LoadSprite(skillCard.skillCardImgPath)
    end
    local _SetCardBG = function()
        local pathBG = skillCard.isSPSkill and Constants.SkillCardBG.SP or Constants.SkillCardBG.Common[skillCard.skillCardStarLevel]
        compCardBG:LoadSprite(pathBG)
    end
    local _SetSkillCardFrame = function()
        KTool.SetActive(cardFrame.gameObject, true)
        local pathFrame = skillCard.isSPSkill and Constants.SkillCardFrame.SP or Constants.SkillCardFrame.Common[checkInt(skillCard.skillCardStarLevel)]
        compCardFrame:LoadSprite(pathFrame)
    end
    local _SetSkillCardIndex = function()
        if skillCard.isSPSkill then
            KTool.SetActive(skillCard.cardIndex.gameObject, false)
            return
        end
        KTool.SetActive(skillCard.cardIndex.gameObject, true)
        local pathIndex = Constants.SkillCardIndex[skillCard.skillCardStarLevel]
        compCardIndex:LoadSprite(pathIndex)
    end
    local _SetSkillCardTypeIcon = function()
        local condition = skillCard.cardType >= 1 and skillCard.cardType <= 4 and skillCard.isAoe
        local skillCardTypeIconPath = condition and UIBattlingTools.GetSkillTypeAOEIconPath(skillCard.cardType) or
                UIBattlingTools.GetSkillTypeIconPath(skillCard.cardType)
        compCardTypeIcon.isNativeSize = false
        compCardTypeIcon:LoadSprite(skillCardTypeIconPath)
    end
    local _SetCardTypeBG = function()
        local pathBG = skillCard.isSPSkill
                and Constants.SkillCardTypeBG.SP or Constants.SkillCardTypeBG.Common[skillCard.skillCardStarLevel]
        compCardTypeBG:LoadSprite(pathBG)
    end
    --------------------- SetInfo
    _SetCardIcon()
    _SetCardBG()
    _SetSkillCardFrame()
    _SetSkillCardIndex()
    _SetSkillCardTypeIcon()
    _SetCardTypeBG()
end
