function UIGamePlayGuideBookDialog:PlayAnimationFingerPoint(position)
    if not IsNull(self.FingerNode) then
        KTool.SetParent(self.FingerNode.gameObject, self.Root_SkillCardPool.gameObject)
        self.FingerNode.transform.position = position or Vector3.New(99999, 99999)
    end
    
    -- print("->PlayAnimationFingerPoint:", position, not isNull(position))
    if not IsNull(self.animatorFinger) then
        self.animatorFinger.enabled = not isNull(position)
        self.animatorFinger:Play("Play", 0, 0)
    end
end

function UIGamePlayGuideBookDialog:PlayAnimationFingerDrag(father)
    if not IsNull(father) then
        KTool.SetParent(self.FingerNode.gameObject, father.gameObject)
        self.FingerNode.anchoredPosition = Vector2.New(0,0)
        self.animatorFinger:Play("Idle", 0, 0)
    else
        if isNull(self.Root_SkillCardPool) then return end
        KTool.SetParent(self.FingerNode.gameObject, self.Root_SkillCardPool.gameObject)
        self.FingerNode.position = Vector3.New(99999, 99999)
    end
end

--- 设置互斥界面的显示状态
---@param state any
function UIGamePlayGuideBookDialog:SetMutexPageShowState(state)
    for i, pageId in ipairs(mutexPage) do
        local dialog = UIModule.CurrentScreen:GetDialog(pageId)
        if not isNull(dialog) then
            dialog.CacheCanvas.enabled = state
        end
    end
end

